// Secret Key for HMAC-SHA256 and AES-256 (Server side only)
const HMAC_SECRET = process.env.HMAC_SECRET || "ARMIN_SANAT_SAMIN_SECURE_DIAG_P_MOTOR_2026_SALT";
const AES_KEY = crypto.createHash("sha256").update(HMAC_SECRET).digest();

// AES-256 Encryption helper for sensitive fields
function encryptAes256(text: string): string {
  try {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv("aes-256-cbc", AES_KEY, iv);
    let encrypted = cipher.update(text, "utf8", "hex");
    encrypted += cipher.final("hex");
    return `${iv.toString("hex")}:${encrypted}`;
  } catch (e) {
    return `enc_${Buffer.from(text).toString("base64")}`;
  }
}

function decryptAes256(encryptedText: string): string {
  try {
    const [ivHex, cipherHex] = encryptedText.split(":");
    if (!ivHex || !cipherHex) return encryptedText;
    const iv = Buffer.from(ivHex, "hex");
    const decipher = crypto.createDecipheriv("aes-256-cbc", AES_KEY, iv);
    let decrypted = decipher.update(cipherHex, "hex", "utf8");
    decrypted += decipher.final("utf8");
    return decrypted;
  } catch (e) {
    return encryptedText;
  }
}

