// ============================================================
// EXACT KOTLIN ALGORITHM IMPLEMENTATION (ActivationManager.kt)
// Formula: N * 191 همراه با مدولاسیون در صورت بزرگتر شدن از ۶ رقم
// ============================================================
function calculateActivationCode(deviceCodeStr: string): string {
  const cleanCode = (deviceCodeStr || "").replace(/[^0-9]/g, "").trim();
  if (!cleanCode) return "000000";

  const num = parseInt(cleanCode, 10);
  if (isNaN(num) || num <= 0) return "000000";

  // فرمول ثابت و قطعی: N * 191
  const raw = num * 191;

  // اگر ۶ رقمی بود همان را برمی‌گرداند، در غیر این صورت مدولاسیون انجام می‌شود
  let finalCode: number;
  if (raw >= 100000 && raw <= 999999) {
    finalCode = raw;
  } else {
    finalCode = (raw % 900000) + 100000;
  }

  return String(finalCode).padStart(6, "0");
}

function generateHmacSignature(deviceCode: string, activationCode: string, timestamp: string): string {
  return crypto
    .createHmac("sha256", HMAC_SECRET)
    .update(`${deviceCode}:${activationCode}:${timestamp}`)
    .digest("hex");
}

// Rate Limiting Map
const rateLimitMap = new Map<string, { count: number; lastTime: number }>();
function checkRateLimit(ip: string, limit = 10, windowMs = 60000): boolean {
  const now = Date.now();
  const record = rateLimitMap.get(ip) || { count: 0, lastTime: now };
  if (now - record.lastTime > windowMs) {
    record.count = 1;
    record.lastTime = now;
  } else {
    record.count += 1;
  }
  rateLimitMap.set(ip, record);
  return record.count <= limit;
}

